1	#pragma once
2	
3	// TMA_DISABLE_ALL: when defined, disable load/store warps entirely
4	// and let MMA warps work without pipeline synchronization
5	// #define TMA_DISABLE_ALL
6	
7	#include "utils.cuh"
8	
9	template <int D, int CHUNK = 16>
10	struct K2Layouts {
11	    using MMALayout = decltype(tile_to_shape(
12	        GMMA::Layout_K_INTER_Atom<cute::bfloat16_t>{},
13	        make_shape(Int<CHUNK>{}, Int<D>{}),
14	        LayoutLeft{}
15	    ));
16	    using TransposedMMALayout = decltype(tile_to_shape(
17	        GMMA::Layout_MN_INTER_Atom<cute::bfloat16_t>{},
18	        make_shape(Int<D>{}, Int<CHUNK>{}),
19	        LayoutRight{}
20	    ));
21	    using VOLayout = MMALayout;
22	    using TransposedVOLayout = TransposedMMALayout;
23	    using BetaSmemLayout = Layout<Shape<Int<32>>, Stride<Int<1>>>;
24	    using StateSmemLayout = decltype(tile_to_shape(
25	        GMMA::Layout_K_INTER_Atom<cute::bfloat16_t>{},
26	        make_shape(Int<D>{}, Int<D>{}),
27	        LayoutLeft{}
28	    ));
29	    using TransposedStateSmemLayout = decltype(tile_to_shape(
30	        GMMA::Layout_MN_INTER_Atom<cute::bfloat16_t>{},
31	        make_shape(Int<D>{}, Int<D>{}),
32	        LayoutRight{}
33	    ));
34	    using GTotalLayout = Layout<Shape<Int<D>>, Stride<Int<1>>>;
35	    using LMLayout = decltype(tile_to_shape(
36	        GMMA::Layout_K_INTER_Atom<cute::bfloat16_t>{},
37	        make_shape(Int<CHUNK>{}, Int<CHUNK>{}),
38	        LayoutLeft{}
39	    ));
40	
41	    using TMABetaSmemLayout = BetaSmemLayout;  // 1D TMA, no dummy dim
42	    using TMAVOLayout = decltype(composition(
43	        VOLayout{}.layout_a(),
44	        VOLayout{}.offset(),
45	        prepend(VOLayout{}.layout_b())
46	    ));
47	    using TMAStateSmemLayout = decltype(composition(
48	        StateSmemLayout{}.layout_a(),
49	        StateSmemLayout{}.offset(),
50	        prepend(StateSmemLayout{}.layout_b())
51	    ));
52	    using TMALMLayout = decltype(composition(
53	        LMLayout{}.layout_a(),
54	        LMLayout{}.offset(),
55	        prepend(LMLayout{}.layout_b())
56	    ));
57	    using TMAGTotalSmemLayout = decltype(prepend(GTotalLayout{}));
58	
59	    // FP32 state layout (K_SW32 atom, same 8x8 atom structure as K_INTER bf16)
60	    using FP32StateSmemLayout = decltype(tile_to_shape(
61	        GMMA::Layout_K_SW32_Atom<float>{},
62	        make_shape(Int<D>{}, Int<D>{}),
63	        LayoutLeft{}
64	    ));
65	    using TMAFP32StateSmemLayout = decltype(composition(
66	        FP32StateSmemLayout{}.layout_a(),
67	        FP32StateSmemLayout{}.offset(),
68	        prepend(FP32StateSmemLayout{}.layout_b())
69	    ));
70	};
71	
72	template <class Layouts, int InputStages, int OutputStages>
73	struct SharedStorageK2 {
74	    using BF16 = cutlass::bfloat16_t;
75	    using VOLayout = typename Layouts::VOLayout;
76	    using BetaSmemLayout = typename Layouts::BetaSmemLayout;
77	    using StateSmemLayout = typename Layouts::StateSmemLayout;
78	    using GTotalLayout = typename Layouts::GTotalLayout;
79	    using LMLayout = typename Layouts::LMLayout;
80	    using MMALayout = typename Layouts::MMALayout;
81	
82	    alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<StateSmemLayout>> state_acc;
83	
84	    struct InputStorage {
85	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<VOLayout>> v;
86	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<BetaSmemLayout>> beta;
87	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<MMALayout>> k_decayed;
88	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<MMALayout>> q_decayed;
89	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<MMALayout>> k_restored;
90	        alignas(128) cute::ArrayEngine<float, cute::cosize_v<GTotalLayout>> g_total;
91	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<LMLayout>> INV;
92	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<LMLayout>> Mqk;
93	    };
94	
95	    struct OutputStorage {
96	        alignas(128) cute::ArrayEngine<BF16, cute::cosize_v<VOLayout>> out;
97	    };
98	
99	    // Anonymous union: pipeline buffers share space with fp32 state conversion buffer.
100	    // FP32 state load/store happens before/after the pipeline loop, so no overlap.
101	    union {
102	        struct {
103	            InputStorage input[InputStages];
104	            OutputStorage output[OutputStages];
105	        };
106	        alignas(128) char state_fp32_buf[cute::cosize_v<StateSmemLayout> * sizeof(float)];
107	    };
108	
109	    typename cutlass::PipelineTmaAsync<InputStages>::SharedStorage load_pipeline;
110	    typename cutlass::PipelineAsync<OutputStages>::SharedStorage store_pipeline;
111	    alignas(16) cutlass::arch::ClusterTransactionBarrier state_acc_tma_barrier;
112	};
113	
114	// ==================== Kernel 2: Recurrence ====================
115	template <
116	    class TmaLoadV,
117	    class TmaLoadBeta,
118	    class TmaLoadWsKD, class TmaLoadWsQD, class TmaLoadWsKR,
119	    class TmaLoadWsGT, class TmaLoadWsINV, class TmaLoadWsMqk,
120	    class TmaLoadState,
121	    class TmaStoreState,
122	    class TmaStoreOut,
123	    int CHUNK,
124	    int D,
125	    int InputStages,
126	    int OutputStages,
127	    int NumThreads,
128	    bool HasStateIn = true,
129	    bool HasStateOut = true,
130	    bool StateFP32 = false,
131	    bool IsVarlen = true
132	>
133	__global__ void __launch_bounds__(NumThreads) _flash_kda_fwd_recurrence(
134	    CUTE_GRID_CONSTANT TmaLoadV const tma_load_v,
135	    CUTE_GRID_CONSTANT TmaLoadBeta const tma_load_beta,
136	    CUTE_GRID_CONSTANT TmaLoadWsKD const tma_load_ws_kd,
137	    CUTE_GRID_CONSTANT TmaLoadWsQD const tma_load_ws_qd,
138	    CUTE_GRID_CONSTANT TmaLoadWsKR const tma_load_ws_kr,
139	    CUTE_GRID_CONSTANT TmaLoadWsGT const tma_load_ws_gt,
140	    CUTE_GRID_CONSTANT TmaLoadWsINV const tma_load_ws_inv,
141	    CUTE_GRID_CONSTANT TmaLoadWsMqk const tma_load_ws_mqk,
142	    CUTE_GRID_CONSTANT TmaLoadState const tma_load_initial_state,
143	    CUTE_GRID_CONSTANT TmaStoreState const tma_store_final_state,
144	    CUTE_GRID_CONSTANT TmaStoreOut const tma_store_out,
145	    cutlass::bfloat16_t* out_raw_ptr,
146	    int T_total,
147	    int H,
148	    int N,
149	    int64_t const* cu_seqlens,
150	    int total_tiles
151	) {
152	    using BF16 = cutlass::bfloat16_t;
153	    using FP16 = cutlass::half_t;
154	    using Layouts = K2Layouts<D, CHUNK>;
155	    using MMALayout = typename Layouts::MMALayout;
156	    using TransposedMMALayout = typename Layouts::TransposedMMALayout;
157	    using VOLayout = typename Layouts::VOLayout;
158	    using TransposedVOLayout = typename Layouts::TransposedVOLayout;
159	    using BetaSmemLayout = typename Layouts::BetaSmemLayout;
160	    using StateSmemLayout = typename Layouts::StateSmemLayout;
161	    using TransposedStateSmemLayout = typename Layouts::TransposedStateSmemLayout;
162	    using GTotalLayout = typename Layouts::GTotalLayout;
163	    using LMLayout = typename Layouts::LMLayout;
164	    using TMAVOLayout = typename Layouts::TMAVOLayout;
165	    using TMABetaSmemLayout = typename Layouts::TMABetaSmemLayout;
166	    using TMAStateSmemLayout = typename Layouts::TMAStateSmemLayout;
167	    using TMALMLayout = typename Layouts::TMALMLayout;
168	    using TMAGTotalSmemLayout = typename Layouts::TMAGTotalSmemLayout;
169	    constexpr int kWarpSize = 32;
170	    constexpr int kComputeThreads = 128;
171	
172	    // Transaction bytes: v + beta + k_decayed + q_decayed + k_restored + g_total + INV + Mqk
173	    constexpr uint32_t kTmaTransactionBytes =
174	#ifndef TMA_DISABLE_ALL
175	        uint32_t(cute::cosize_v<VOLayout>) * uint32_t(sizeof(BF16)) +
176	        uint32_t(32) * uint32_t(sizeof(BF16)) +  // beta (bf16, sigmoid fused)
177	        uint32_t(cute::cosize_v<MMALayout>) * uint32_t(sizeof(BF16)) * 3 +  // k_decayed, q_decayed, k_restored
178	        uint32_t(cute::cosize_v<GTotalLayout>) * uint32_t(sizeof(float)) +    // g_total
179	        uint32_t(cute::cosize_v<LMLayout>) * uint32_t(sizeof(BF16)) * 2 +    // INV, Mqk
180	#endif
181	        0u;
182	
183	    // --- shared memory
184	    extern __shared__ __align__(128) unsigned char shared_mem[];
185	    using SharedStorageT = SharedStorageK2<Layouts, InputStages, OutputStages>;
186	    SharedStorageT& shared_storage = *reinterpret_cast<SharedStorageT*>(shared_mem);
187	
188	    // --- warp specialization
189	    int warp_id = threadIdx.x / kWarpSize;
190	    WarpRole warp_role = WarpRole::NonParticipant;
191	    if (warp_id < kComputeThreads / kWarpSize) {
192	        warp_role = WarpRole::MMA;
193	    } else if (warp_id < kComputeThreads / kWarpSize + 1) {
194	        warp_role = WarpRole::LOAD_QKG;
195	    } else if (warp_id < kComputeThreads / kWarpSize + 2) {
196	        warp_role = WarpRole::STORE;
197	    }
198	
199	#ifndef TMA_DISABLE_ALL
200	    using LoadPipelineState = cutlass::PipelineState<InputStages>;
201	    using LoadPipeline = cutlass::PipelineTmaAsync<InputStages>;
202	    LoadPipeline load_pipeline = make_load_pipeline<InputStages>(
203	        shared_storage.load_pipeline,
204	        kTmaTransactionBytes,
205	        warp_role, 1, kComputeThreads
206	    );
207	    using StorePipelineState = cutlass::PipelineState<OutputStages>;
208	    using StorePipeline = cutlass::PipelineAsync<OutputStages>;
209	    StorePipeline store_pipeline = make_store_pipeline<OutputStages>(
210	        shared_storage.store_pipeline,
211	        warp_role, kComputeThreads, 1
212	    );
213	#endif
214	
215	    // --- per-block sequence info
216	    int seq_idx  = blockIdx.x;
217	    int head_idx = blockIdx.y;
218	    int64_t bos, eos;
219	    int tile_base;
220	
221	    if constexpr (IsVarlen) {
222	        bos = cu_seqlens[seq_idx];
223	        eos = cu_seqlens[seq_idx + 1];
224	        // Compute tile_base via linear scan (no host-precomputed table)
225	        tile_base = 0;
226	        for (int i = 0; i < seq_idx; i++) {
227	            tile_base += (int(cu_seqlens[i + 1] - cu_seqlens[i]) + CHUNK - 1) / CHUNK;
228	        }
229	    } else {
230	        int T_seq = T_total / N;
231	        bos = seq_idx * T_seq;
232	        eos = bos + T_seq;
233	        tile_base = seq_idx * ((T_seq + CHUNK - 1) / CHUNK);
234	    }
235	    int seq_len  = int(eos - bos);
236	    int t_tiles  = (seq_len + CHUNK - 1) / CHUNK;
237	    bool lane_predicate = cute::elect_one_sync();
238	
239	    // --- Load initial state
240	#ifndef TMA_DISABLE_ALL
241	    if constexpr (HasStateIn && !StateFP32) {
242	        // BF16 state: TMA load directly into state_acc
243	        if (warp_role == WarpRole::LOAD_QKG && lane_predicate) {
244	            using BarrierType = cutlass::arch::ClusterTransactionBarrier::ValueType;
245	            constexpr uint32_t kStateTransactionBytes = cute::cosize_v<StateSmemLayout> * sizeof(BF16);
246	
247	            shared_storage.state_acc_tma_barrier.init(1);
248	            cutlass::arch::fence_barrier_init();  // generic init -> visible to async proxy (TMA complete-tx)
249	            shared_storage.state_acc_tma_barrier.arrive_and_expect_tx(kStateTransactionBytes);
250	
251	            Tensor g_init = tma_load_initial_state.get_tma_tensor(make_shape(N * H, D, D));
252	            auto init_off = g_init.layout()(seq_idx * H + head_idx, 0, 0);
253	            Tensor g_init_tile = make_tensor(g_init.data() + init_off,
254	                make_layout(make_shape(Int<1>{}, Int<D>{}, Int<D>{}), stride(g_init.layout())));
255	            Tensor s_state = make_tensor(make_smem_ptr(shared_storage.state_acc.begin()), TMAStateSmemLayout{});
256	
257	            auto cta_tma_load_state = tma_load_initial_state.get_slice(Int<0>{});
258	            cute::copy(
259	                tma_load_initial_state.with(reinterpret_cast<BarrierType&>(shared_storage.state_acc_tma_barrier)),
260	                cta_tma_load_state.partition_S(g_init_tile),
261	                cta_tma_load_state.partition_D(s_state)
262	            );
263	        }
264	        __syncthreads();
265	        shared_storage.state_acc_tma_barrier.wait(0);
266	        cutlass::arch::fence_view_async_shared();
267	    } else if constexpr (HasStateIn && StateFP32) {
268	        // FP32 state: TMA load fp32 into pipeline buffer, then convert to bf16 in state_acc
269	        using FP32StateSmemLayout = typename Layouts::FP32StateSmemLayout;
270	        using TMAFP32StateSmemLayout = typename Layouts::TMAFP32StateSmemLayout;
271	
272	        if (warp_role == WarpRole::LOAD_QKG && lane_predicate) {
273	            using BarrierType = cutlass::arch::ClusterTransactionBarrier::ValueType;
274	            constexpr uint32_t kFP32StateTransactionBytes = cute::cosize_v<StateSmemLayout> * sizeof(float);
275	
276	            shared_storage.state_acc_tma_barrier.init(1);
277	            cutlass::arch::fence_barrier_init();  // generic init -> visible to async proxy (TMA complete-tx)
278	            shared_storage.state_acc_tma_barrier.arrive_and_expect_tx(kFP32StateTransactionBytes);
279	
280	            Tensor g_init = tma_load_initial_state.get_tma_tensor(make_shape(N * H, D, D));
281	            auto init_off = g_init.layout()(seq_idx * H + head_idx, 0, 0);
282	            Tensor g_init_tile = make_tensor(g_init.data() + init_off,
283	                make_layout(make_shape(Int<1>{}, Int<D>{}, Int<D>{}), stride(g_init.layout())));
284	            Tensor s_fp32 = make_tensor(
285	                make_smem_ptr(reinterpret_cast<float*>(shared_storage.state_fp32_buf)),
286	                TMAFP32StateSmemLayout{});
287	
288	            auto cta_tma_load_state = tma_load_initial_state.get_slice(Int<0>{});
289	            cute::copy(
290	                tma_load_initial_state.with(reinterpret_cast<BarrierType&>(shared_storage.state_acc_tma_barrier)),
291	                cta_tma_load_state.partition_S(g_init_tile),
292	                cta_tma_load_state.partition_D(s_fp32)
293	            );
294	        }
295	        __syncthreads();
296	        shared_storage.state_acc_tma_barrier.wait(0);
297	        cutlass::arch::fence_view_async_shared();
298	
299	        // All threads: convert fp32 -> bf16 with layout transformation
300	        smem_cvt_fp32_to_bf16<FP32StateSmemLayout, StateSmemLayout, D, NumThreads>(
301	            reinterpret_cast<float*>(shared_storage.state_fp32_buf),
302	            shared_storage.state_acc.begin(),
303	            threadIdx.x);
304	        __syncthreads();
305	    } else {
306	        // No state in: zero-initialize state_acc
307	        {
308	            BF16* buf = shared_storage.state_acc.begin();
309	            constexpr int kTotal = cute::cosize_v<StateSmemLayout>;
310	            for (int i = threadIdx.x; i < kTotal; i += NumThreads) {
311	                buf[i] = BF16(0);
312	            }
313	        }
314	        // generic writes -> visible to async proxy (TMA state store covers t_tiles==0)
315	        cutlass::arch::fence_view_async_shared();
316	        __syncthreads();
317	    }
318	#endif
319	
320	#ifndef TMA_DISABLE_ALL
321	    __syncthreads();
322	
323	    // --- LOAD warp: issue TMA loads for v, beta, and workspace intermediates
324	    if (warp_role == WarpRole::LOAD_QKG && lane_predicate) {
325	        Tensor g_v = tma_load_v.get_tma_tensor(make_shape(H, T_total, D));
326	        Tensor g_beta = tma_load_beta.get_tma_tensor(make_shape(H * T_total));
327	
328	        // Workspace gmem tensors
329	        auto g_ws_kd = tma_load_ws_kd.get_tma_tensor(make_shape(H * total_tiles, CHUNK, D));
330	        auto g_ws_qd = tma_load_ws_qd.get_tma_tensor(make_shape(H * total_tiles, CHUNK, D));
331	        auto g_ws_kr = tma_load_ws_kr.get_tma_tensor(make_shape(H * total_tiles, CHUNK, D));
332	        auto g_ws_gt = tma_load_ws_gt.get_tma_tensor(make_shape(H * total_tiles, D));
333	        auto g_ws_inv = tma_load_ws_inv.get_tma_tensor(make_shape(H * total_tiles, CHUNK, CHUNK));
334	        auto g_ws_mqk = tma_load_ws_mqk.get_tma_tensor(make_shape(H * total_tiles, CHUNK, CHUNK));
335	
336	        LoadPipelineState load_write = cutlass::make_producer_start_state<LoadPipeline>();
337	        auto cta_tma_load_v = tma_load_v.get_slice(Int<0>{});
338	        auto cta_tma_load_beta = tma_load_beta.get_slice(Int<0>{});
339	        auto cta_ws_kd = tma_load_ws_kd.get_slice(Int<0>{});
340	        auto cta_ws_qd = tma_load_ws_qd.get_slice(Int<0>{});
341	        auto cta_ws_kr = tma_load_ws_kr.get_slice(Int<0>{});
342	        auto cta_ws_gt = tma_load_ws_gt.get_slice(Int<0>{});
343	        auto cta_ws_inv = tma_load_ws_inv.get_slice(Int<0>{});
344	        auto cta_ws_mqk = tma_load_ws_mqk.get_slice(Int<0>{});
345	
346	        for (int t = 0; t < t_tiles; ++t) {
347	            load_pipeline.producer_acquire(load_write);
348	            using LoadBarrierType = typename LoadPipeline::ProducerBarrierType;
349	            LoadBarrierType* tma_barrier = load_pipeline.producer_get_barrier(load_write);
350	            int stage = load_write.index();
351	            int ws_idx = head_idx * total_tiles + tile_base + t;
352	
353	            // TMA load v
354	            auto v_off = g_v.layout()(head_idx, int(bos) + t * CHUNK, 0);
355	            Tensor g_v_tile = make_tensor(g_v.data() + v_off,
356	                make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{}), stride(g_v.layout())));
357	            Tensor s_v_tile = make_tensor(make_smem_ptr(shared_storage.input[stage].v.begin()), TMAVOLayout{});
358	            cute::copy(tma_load_v.with(*tma_barrier),
359	                cta_tma_load_v.partition_S(g_v_tile), cta_tma_load_v.partition_D(s_v_tile));
360	
361	            // TMA load beta (1D)
362	            int beta_linear = head_idx * T_total + (int(bos) + t * CHUNK);
363	            int beta_aligned = beta_linear & ~7;
364	            auto beta_off = g_beta.layout()(beta_aligned);
365	            Tensor g_beta_tile = make_tensor(g_beta.data() + beta_off, BetaSmemLayout{});
366	            Tensor s_beta_tile = make_tensor(make_smem_ptr(shared_storage.input[stage].beta.begin()), TMABetaSmemLayout{});
367	            cute::copy(tma_load_beta.with(*tma_barrier),
368	                cta_tma_load_beta.partition_S(g_beta_tile), cta_tma_load_beta.partition_D(s_beta_tile));
369	
370	            // TMA load workspace: k_decayed
371	            {
372	                auto off = g_ws_kd.layout()(ws_idx, 0, 0);
373	                Tensor g_tile = make_tensor(g_ws_kd.data() + off,
374	                    make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{}), stride(g_ws_kd.layout())));
375	                Tensor s_tile = make_tensor(make_smem_ptr(shared_storage.input[stage].k_decayed.begin()), TMAVOLayout{});
376	                cute::copy(tma_load_ws_kd.with(*tma_barrier), cta_ws_kd.partition_S(g_tile), cta_ws_kd.partition_D(s_tile));
377	            }
378	            // q_decayed
379	            {
380	                auto off = g_ws_qd.layout()(ws_idx, 0, 0);
381	                Tensor g_tile = make_tensor(g_ws_qd.data() + off,
382	                    make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{}), stride(g_ws_qd.layout())));
383	                Tensor s_tile = make_tensor(make_smem_ptr(shared_storage.input[stage].q_decayed.begin()), TMAVOLayout{});
384	                cute::copy(tma_load_ws_qd.with(*tma_barrier), cta_ws_qd.partition_S(g_tile), cta_ws_qd.partition_D(s_tile));
385	            }
386	            // k_restored
387	            {
388	                auto off = g_ws_kr.layout()(ws_idx, 0, 0);
389	                Tensor g_tile = make_tensor(g_ws_kr.data() + off,
390	                    make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<D>{}), stride(g_ws_kr.layout())));
391	                Tensor s_tile = make_tensor(make_smem_ptr(shared_storage.input[stage].k_restored.begin()), TMAVOLayout{});
392	                cute::copy(tma_load_ws_kr.with(*tma_barrier), cta_ws_kr.partition_S(g_tile), cta_ws_kr.partition_D(s_tile));
393	            }
394	            // g_total
395	            {
396	                auto off = g_ws_gt.layout()(ws_idx, 0);
397	                Tensor g_tile = make_tensor(g_ws_gt.data() + off,
398	                    make_layout(make_shape(Int<1>{}, Int<D>{}), stride(g_ws_gt.layout())));
399	                Tensor s_tile = make_tensor(make_smem_ptr(shared_storage.input[stage].g_total.begin()), TMAGTotalSmemLayout{});
400	                cute::copy(tma_load_ws_gt.with(*tma_barrier), cta_ws_gt.partition_S(g_tile), cta_ws_gt.partition_D(s_tile));
401	            }
402	            // INV
403	            {
404	                auto off = g_ws_inv.layout()(ws_idx, 0, 0);
405	                Tensor g_tile = make_tensor(g_ws_inv.data() + off,
406	                    make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<CHUNK>{}), stride(g_ws_inv.layout())));
407	                Tensor s_tile = make_tensor(make_smem_ptr(shared_storage.input[stage].INV.begin()), TMALMLayout{});
408	                cute::copy(tma_load_ws_inv.with(*tma_barrier), cta_ws_inv.partition_S(g_tile), cta_ws_inv.partition_D(s_tile));
409	            }
410	            // Mqk
411	            {
412	                auto off = g_ws_mqk.layout()(ws_idx, 0, 0);
413	                Tensor g_tile = make_tensor(g_ws_mqk.data() + off,
414	                    make_layout(make_shape(Int<1>{}, Int<CHUNK>{}, Int<CHUNK>{}), stride(g_ws_mqk.layout())));
