576	            SFragT v_bf16[2];
577	            #pragma unroll
578	            for (int i = 0; i < 2; ++i) {
579	                Tensor v_block = local_tile(v_tile, make_shape(Int<16>{}, Int<16>{}), make_coord(0, warp_id * 2 + i));
