669	            SFragT ring_S_acc[2][PREFETCH];
670	            float ring_g0[PREFETCH], ring_g1[PREFETCH];
671	
672	            #pragma unroll
673	            for (int i = 0; i < PREFETCH; ++i) {
674	                Tensor kr_block = local_tile(k_restored_t, make_shape(Int<16>{}, Int<16>{}), make_coord(i, 0));
