709	
710	                #pragma unroll
711	                for (int bi = 0; bi < 2; ++bi) {
712	                    #pragma unroll
713	                    for (int a = 0; a < 2; ++a) {
714	                        #pragma unroll
715	                        for (int d = 0; d < 2; ++d) {
